using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    public static ReportingConfiguration CreateTelemetryConfig()
    {
        // Telemetry mode: captures token usage and latency from OpenTelemetry traces.
        return new ReportingConfiguration(
            new DiskBasedResultStore(Path.Combine(StoragePath, "telemetry")),
            evaluators: [new TokenCountEvaluator()]);
    }

    public static ReportingConfiguration CreateQualityConfig(IChatClient judgeChatClient)
    {
        // Quality mode: evaluates relevance, coherence, and fluency.
        return new ReportingConfiguration(
            new DiskBasedResultStore(Path.Combine(StoragePath, "quality")),
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(judgeChatClient));
    }

    public static ReportingConfiguration CreateCompareConfig(IChatClient judgeChatClient)
    {
        // Compare mode: evaluates equivalence between baseline and candidate responses.
        return new ReportingConfiguration(
            new DiskBasedResultStore(Path.Combine(StoragePath, "compare")),
            evaluators: [new EquivalenceEvaluator()],
            chatConfiguration: new ChatConfiguration(judgeChatClient));
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class TelemetryEvalTests
{
    private static ScenarioRun? _scenarioRun;
    private static ReportingConfiguration? _config;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        _config = EvalConfig.CreateTelemetryConfig();
        _scenarioRun = await _config.CreateScenarioRunAsync(
            "telemetry-baseline",
            additionalTags: ["telemetry"]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [TestMethod]
    public async Task Coach_Response_Reports_TokenUsage()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is dependency injection?")
        };

        var response = new ChatMessage(
            ChatRole.Assistant,
            "Dependency injection is a design pattern that allows decoupling components from their dependencies.");

        await _scenarioRun!.EvaluateAsync(messages, response);

        var results = _scenarioRun.GetEvaluationResults();
        Assert.IsTrue(results.Count > 0, "Expected at least one evaluation result.");
    }
}

using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class QualityEvalTests
{
    private static ScenarioRun? _scenarioRun;
    private static ReportingConfiguration? _config;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        var judge = new AzureOpenAIClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            new DefaultAzureCredential())
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        _config = EvalConfig.CreateQualityConfig(judge);
        _scenarioRun = await _config.CreateScenarioRunAsync(
            "quality-baseline",
            additionalTags: ["quality"]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [TestMethod]
    public async Task Coach_Response_MeetsQualityThreshold()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain the SOLID principles briefly.")
        };

        var response = new ChatMessage(
            ChatRole.Assistant,
            """
            SOLID stands for five design principles:
            1. Single Responsibility – a class should have one reason to change.
            2. Open/Closed – open for extension, closed for modification.
            3. Liskov Substitution – subtypes must be substitutable for their base types.
            4. Interface Segregation – prefer small, specific interfaces.
            5. Dependency Inversion – depend on abstractions, not concretions.
            """);

        await _scenarioRun!.EvaluateAsync(messages, response);

        var results = _scenarioRun.GetEvaluationResults();
        foreach (var result in results)
        {
            if (result.Rating?.NumericValue is not null)
            {
                Assert.IsTrue(
                    result.Rating.NumericValue >= 3,
                    $"Evaluator '{result.Metric.Name}' scored {result.Rating.NumericValue}, below threshold 3.");
            }
        }
    }
}

using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class CompareEvalTests
{
    private static ScenarioRun? _scenarioRun;
    private static ReportingConfiguration? _config;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        var judge = new AzureOpenAIClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            new DefaultAzureCredential())
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        _config = EvalConfig.CreateCompareConfig(judge);
        _scenarioRun = await _config.CreateScenarioRunAsync(
            "compare-candidate-vs-baseline",
            additionalTags: ["compare"]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [TestMethod]
    public async Task Coach_Response_EquivalentToBaseline()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is dependency injection?")
        };

        var baseline = new ChatMessage(
            ChatRole.Assistant,
            "Dependency injection is a technique where an object's dependencies are provided externally rather than created internally.");

        var candidate = new ChatMessage(
            ChatRole.Assistant,
            "DI is a pattern that supplies components with their dependencies from the outside, promoting loose coupling.");

        // Evaluate candidate against baseline for equivalence.
        await _scenarioRun!.EvaluateAsync(
            messages,
            candidate,
            additionalContext:
            [
                new EvaluationContext("baseline", baseline.Text ?? string.Empty)
            ]);

        var results = _scenarioRun.GetEvaluationResults();
        Assert.IsTrue(results.Count > 0, "Expected equivalence evaluation results.");
    }
}

