using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class QualityEvalTests
{
    private static ScenarioRun? _scenarioRun;
    private static ReportingConfiguration? _config;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        var judge = new AzureOpenAIClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            new DefaultAzureCredential())
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        _config = EvalConfig.CreateQualityConfig(judge);
        _scenarioRun = await _config.CreateScenarioRunAsync(
            "quality-baseline",
            additionalTags: ["quality"]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [TestMethod]
    public async Task Coach_Response_MeetsQualityThreshold()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain the SOLID principles briefly.")
        };

        var response = new ChatMessage(
            ChatRole.Assistant,
            """
            SOLID stands for five design principles:
            1. Single Responsibility – a class should have one reason to change.
            2. Open/Closed – open for extension, closed for modification.
            3. Liskov Substitution – subtypes must be substitutable for their base types.
            4. Interface Segregation – prefer small, specific interfaces.
            5. Dependency Inversion – depend on abstractions, not concretions.
            """);

        await _scenarioRun!.EvaluateAsync(messages, response);

        var results = _scenarioRun.GetEvaluationResults();
        foreach (var result in results)
        {
            if (result.Rating?.NumericValue is not null)
            {
                Assert.IsTrue(
                    result.Rating.NumericValue >= 3,
                    $"Evaluator '{result.Metric.Name}' scored {result.Rating.NumericValue}, below threshold 3.");
            }
        }
    }
}

