using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class CompareEvalTests
{
    private static ScenarioRun? _scenarioRun;
    private static ReportingConfiguration? _config;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        var judge = new AzureOpenAIClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            new DefaultAzureCredential())
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        _config = EvalConfig.CreateCompareConfig(judge);
        _scenarioRun = await _config.CreateScenarioRunAsync(
            "compare-candidate-vs-baseline",
            additionalTags: ["compare"]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [TestMethod]
    public async Task Coach_Response_EquivalentToBaseline()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is dependency injection?")
        };

        var baseline = new ChatMessage(
            ChatRole.Assistant,
            "Dependency injection is a technique where an object's dependencies are provided externally rather than created internally.");

        var candidate = new ChatMessage(
            ChatRole.Assistant,
            "DI is a pattern that supplies components with their dependencies from the outside, promoting loose coupling.");

        // Evaluate candidate against baseline for equivalence.
        await _scenarioRun!.EvaluateAsync(
            messages,
            candidate,
            additionalContext:
            [
                new EvaluationContext("baseline", baseline.Text ?? string.Empty)
            ]);

        var results = _scenarioRun.GetEvaluationResults();
        Assert.IsTrue(results.Count > 0, "Expected equivalence evaluation results.");
    }
}

